contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint d) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (d)); require(d <= 1000000000000000000000000000000);
        require(d >= 1 ether);
        require(address(this).balance >= d);

        c.Deposit{value: d}(); if (__ESBMC_reverted()) return;

        uint recordedBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint contractBefore = address(c).balance;
        uint testBefore = address(this).balance;

        c.Collect(d); if (__ESBMC_reverted()) return;

        assert(
            c.balances(address(this)) == 0 &&
            recordedBefore == d &&
            address(c).balance == contractBefore - d &&
            address(this).balance == testBefore + d
        );
    }

    receive() external payable {}
}

