pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _run(uint256 d) internal {
        d = bound(d, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(d >= 1 ether);
        vm.assume(address(this).balance >= d);
        try c.Deposit{value: d}() {} catch { return; }
        uint256 recordedBefore;
        try c.balances(address(this)) returns (uint256 __r) { recordedBefore = __r; } catch { return; }
        uint contractBefore = address(c).balance;
        uint testBefore = address(this).balance;
        try c.Collect(d) {} catch { return; }
        assertTrue(c.balances(address(this)) == 0 &&
            recordedBefore == d &&
            address(c).balance == contractBefore - d &&
            address(this).balance == testBefore + d);
    }

    function testFuzz_run(uint256 d) public {
        _run(d);
    }

    receive() external payable {}
}
